const description: { en: string; ja: string } = {"en":"Three heads of three pointed lobes each, on one stalk: a central head with its lobes up, down to the left and down to the right, and a head each side lower down, turned a little differently. Each lobe is the lens between two arcs, with a white vein up it, and a small ring stands where a head's three lobes meet. A bar for the stalk rises up the middle to the central ring and a curved band lies behind the heads, both cut a white line short of the heads in front. The band is built first, then the stalk, then the central head, then the left and the right one where they stand.","ja":"一本の茎に、とがった三つの裂片をもつ葉を三枚置きます。真ん中の葉は裂片を上、左下、右下に向け、左右の葉はそれより低く、向きを少し変えます。裂片はどれも二つの弧にはさまれた形で、白い葉脈を一本通し、葉の三つの裂片が出会うところに小さな輪を置きます。茎は真ん中を上へ通る棒で、先は中央の輪に届き、葉の後ろに曲がった帯を置きます。どちらも前にある葉からは白い線一本分だけ離します。帯、茎、真ん中の葉、左の葉、右の葉の順に、その場で作図します。"};

export default construction;
export { construction, description };
